# 11b_simB_fit.R: Simulation B model comparison on simulated abundance matrices (see 11a). 500 sites (productivity x ~ U(0,1); independent nuisance predictor N ~ N(0,1) that does not affect communities),
# 50 replicates per scenario (logistic generalist dominance vs constant-dominance control), random site-level 70/30 split, orders 2, 3, 4, 5, 8, responses: incidence (Sorensen-type), relative abundance, occupancy-associated and heterogeneity components.
# Models: spread-only, additive nonlinear position, explicit spread-by-position interaction (three endpoint-shrinkage levels); identical sets, bases (training-site), constraints, penalties, links. Replicates are never selected on results.
# Compositional information per (replicate, order): sharing probability of training sets (>= 0.10); environmental information: matched-support flag (spreads supported at both low and high position). Run from final/ (ZG_LIB6 set).
RUN_TRUTH <- "0"; Sys.setenv(RUN_TRUTH = "0"); source("revision_sim/11a_simB_truth.R"); NC <- as.integer(Sys.getenv("NCORES", "9")); NREP <- as.integer(Sys.getenv("NREP", "50")); M <- 3000L
TRU <- read.csv("revision_sim/tables/simB_truth_surfaces.csv"); KEEPSURF <- list(resp = c("incidence", "relative"), ord = c(2, 5))
one <- function(job) { scn <- job$scn; rep <- job$rep; set.seed(30000 + 1000 * (scn == "control") + rep); n <- 500; x <- runif(n); env <- data.frame(P = x, N = rnorm(n)); P <- comm_p(x, scn); cnt <- t(vapply(seq_len(n), function(i) rmultinom(1, N_TOT, P[i, ])[, 1], numeric(nrow(sp)))); colnames(cnt) <- sp$species; stopifnot(all(rowSums(cnt) == N_TOT))
  perm <- sample(n); tr <- sort(perm[1:350]); te <- sort(perm[351:500]); R <- list(); S <- list()
  for (k in ORDERS) { il_tr <- sample_sets(length(tr), k, M, seed = 100000L + 1000L * rep + k); il_te <- sample_sets(length(te), k, M, seed = 200000L + 1000L * rep + k); rtr <- resp_all(cnt[tr, ], il_tr); rte <- resp_all(cnt[te, ], il_te); sharing <- mean(rtr$incidence[rtr$keep] < 1)
    for (rn in RESP_NAMES) { ktr <- rtr$keep & is.finite(rtr[[rn]]); kte <- rte$keep & is.finite(rte[[rn]]); y_tr <- rtr[[rn]][ktr]; y_te <- rte[[rn]][kte]; w_tr <- if (rn == "incidence") rtr$trials_inc[ktr] else rep(1, sum(ktr)); w_te <- if (rn == "incidence") rte$trials_inc[kte] else rep(1, sum(kte))
      tt <- TRU[TRU$scenario == scn & TRU$order == k, ]; resp_t <- tt[[rn]]; truth <- list(eta = qlogis(pmin(pmax(resp_t, 1e-6), 1 - 1e-6)), resp = resp_t)
      ev <- evaluate_order(env, tr, te, k, il_tr[ktr, , drop = FALSE], il_te[kte, , drop = FALSE], y_tr, y_te, w_tr, w_te, truth, MU_P, SD_P, keep_surface = (rn %in% KEEPSURF$resp && k %in% KEEPSURF$ord))
      r <- ev$rows; r$scenario <- scn; r$replicate <- rep; r$response <- rn; r$sharing_probability <- sharing; r$n_train_sets <- sum(ktr); R[[length(R) + 1]] <- r; if (!is.null(ev$surf)) { s <- ev$surf; s$scenario <- scn; s$replicate <- rep; s$response <- rn; S[[length(S) + 1]] <- s } } }
  list(r = do.call(rbind, R), s = do.call(rbind, S)) }
jobs <- do.call(c, lapply(c("logistic", "control"), function(sn) lapply(seq_len(NREP), function(r) list(scn = sn, rep = r)))); t0 <- Sys.time(); RES <- mclapply(jobs, one, mc.cores = NC, mc.preschedule = FALSE); cat("elapsed", format(Sys.time() - t0), "bad", sum(!vapply(RES, is.list, TRUE)), "\n")
M_ <- bind_rows(lapply(RES, function(x) if (is.list(x)) x$r)); S_ <- bind_rows(lapply(RES, function(x) if (is.list(x)) x$s)); write.csv(M_, "revision_sim/tables/simB_metrics.csv", row.names = FALSE); write.csv(S_, "revision_sim/tables/simB_surfaces.csv", row.names = FALSE); cat("rows", nrow(M_), nrow(S_), "nonconverged", sum(!M_$converged), "\n")
